//! User programs embedded into the kernel image.
//!
//! Until there is a file system (M3), `spawn` resolves program names
//! against this table. It is generated by `build.rs` from
//! `user/tests/src/bin/*.rs`.

include!(concat!(env!("OUT_DIR"), "/programs.rs"));

/// The ELF image of program `name` (`hello` or `/bin/hello`).
pub fn find(name: &str) -> Option<&'static [u8]> {
    let name = name.strip_prefix("/bin/").unwrap_or(name);
    PROGRAMS.iter().find(|(n, _)| *n == name).map(|(_, elf)| *elf)
}

/// Names of all embedded programs.
pub fn names() -> impl Iterator<Item = &'static str> {
    PROGRAMS.iter().map(|(n, _)| *n)
}
